'use strict';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let language=new URLSearchParams(location.search).get('lang');
if(!['id','en'].includes(language)){try{language=localStorage.getItem('cs-report-grade11-language')||'en';}catch{language='en';}}
if(!['id','en'].includes(language))language='en';
const t=(id,en)=>language==='id'?id:en;
const tx=pair=>Array.isArray(pair)?pair[language==='id'?0:1]:pair;
let storageKey=null,practice={lessons:{}},storageAvailable=true,currentLesson=null,toastTimer;
function teacherMode(){return g11TeacherVerified===true&&g11Session?.isTeacherPreview===true;}
function lessonRecord(id){if(!practice.lessons[id])practice.lessons[id]={done:false,evidence:'',reflection:'',quiz:{draft:[],best:null,last:null}};return practice.lessons[id];}
function restorePractice(){storageKey='cs-report-grade11-ai-v1:'+encodeURIComponent(g11Session.id);try{const raw=JSON.parse(localStorage.getItem(storageKey)||'null');if(raw?.lessons&&typeof raw.lessons==='object')for(const l of LESSONS){const r=raw.lessons[l.id];if(r&&typeof r==='object'){const q=r.quiz||{};practice.lessons[l.id]={done:r.done===true,evidence:typeof r.evidence==='string'?r.evidence:'',reflection:typeof r.reflection==='string'?r.reflection:'',quiz:{draft:Array.isArray(q.draft)?q.draft.map(v=>Number.isInteger(v)&&v>=0&&v<3?v:null):[],best:Number.isFinite(q.best)?Math.max(0,Math.min(100,q.best)):null,last:Number.isFinite(q.last)?Math.max(0,Math.min(100,q.last)):null}};}}}catch{storageAvailable=false;}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(){try{localStorage.setItem(storageKey,JSON.stringify(practice));return true;}catch{storageAvailable=false;toast(t('Belum tersimpan. Unduh catatan sebelum menutup halaman.','Could not save. Download your notes before closing.'));return false;}}
function sourceByName(name){return BSD_SOURCES.find(s=>s.name===name);}
function localizeShell(){document.documentElement.lang=language;$('language').value=language;const labels={'gate-title':t('Buka AI Studio dari halaman nilaimu.','Open AI Studio from your grade page.'),'gate-copy':t('Cari nama atau NIS di CS.Report, masukkan password siswa, lalu pilih Buka AI Studio.','Search for your name or student ID in CS.Report, enter your student password, then choose Open AI Studio.'),'gate-link':t('Cari nama di CS.Report →','Find your name in CS.Report →'),'skip':t('Langsung ke materi','Skip to content'),'nav-home':t('Pertemuan','Lessons'),'nav-project':t('Demo final','Final demo'),'nav-teacher':t('Panduan guru','Teacher guide'),'book-link':t('Buku nilai ↗','Gradebook ↗'),'footer-copy':t('BSD Code the Future with AI · 14 pertemuan × 2 JP','BSD Code the Future with AI · 14 meetings × 2 periods'),'storage-copy':t('Catatan latihan tersimpan pada browser ini. Nilai resmi dicatat di CS.Report.','Practice notes are saved on this browser. Official grades are recorded in CS.Report.')};for(const[id,text]of Object.entries(labels))$(id).textContent=text;}
function homeHTML(){const done=LESSONS.filter(l=>lessonRecord(l.id).done).length,next=LESSONS.find(l=>!lessonRecord(l.id).done)?.id||14;return '<section class="home-intro"><p class="eyebrow">BSD · CODE THE FUTURE WITH AI</p><h1>'+t('Ubah. Uji. Jelaskan.','Modify. Test. Explain.')+'</h1><p>'+esc(tx(COURSE.startingPoint))+'</p><p>'+t('Tujuan utama: modifikasi proyek AI, uji hasilnya, dan jelaskan cara data, aturan, atau pencarian menghasilkan output.','Main goal: modify AI projects, test their results, and explain how data, rules, or search produce outputs.')+'</p><p>'+t('14 pertemuan × 2 JP. Pilih pertemuan → praktik di BSD → coba tantangan.','14 meetings × 2 periods. Choose a meeting → practise in BSD → try the challenge.')+'</p><a class="btn" href="#lesson/'+next+'">'+t('Lanjutkan belajar →','Continue learning →')+'</a><p class="small" style="margin-top:12px">'+done+'/'+LESSONS.length+' '+t('bukti ditandai siap. Guru memeriksa pemahamanmu.','evidence records marked ready. Your teacher checks understanding.')+'</p></section><h2>'+t('Pilih pertemuan','Choose a meeting')+'</h2><div class="lesson-list">'+LESSONS.map(l=>'<a class="lesson-link" href="#lesson/'+l.id+'"><span class="lesson-number">'+String(l.id).padStart(2,'0')+'</span><div><b>'+esc(tx(l.title))+'</b><small>'+esc(tx(l.result))+'</small></div><strong>'+(lessonRecord(l.id).done?'✓':'→')+'</strong></a>').join('')+'</div><details class="panel optional"><summary>'+t('Referensi bagian sebelumnya','Earlier section references')+'</summary><div><p>'+t('Sudah dikerjakan sampai Webcam Live Classifier menurut guru. Buka kembali hanya jika perlu; catatan ini tidak mengimpor status atau nilai BSD.','Completed through Webcam Live Classifier as reported by the teacher. Revisit only as needed; this page does not import BSD status or grades.')+'</p>'+['tn-webcam-image-classification','tn-card-sorting-activity','tn-machine-learning-image-classification','tn-image-upload-classifier','tn-webcam-live-classifier'].map(n=>{const s=sourceByName(n);return '<p class="source-link"><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+' ↗</a></p>';}).join('')+'</div></details>';}

function lessonHTML(l){const r=lessonRecord(l.id),primary=sourceByName(l.sources[0]);return '<div class="breadcrumbs"><a href="#home">'+t('Pertemuan','Meetings')+'</a> / '+l.id+'</div><header class="lesson-heading"><p class="eyebrow">'+t('PERTEMUAN ','MEETING ')+l.id+' · 80 '+t('MENIT','MINUTES')+'</p><h1>'+esc(tx(l.title))+'</h1><p>'+esc(tx(l.goal))+'</p></header><div class="classroom"><section class="panel task-card"><p class="eyebrow">01 · '+t('KERJAKAN','GET STARTED')+'</p><h2>'+t('Tugas hari ini','Today’s task')+'</h2><p class="bsd-route"><b>BSD:</b> '+l.sources.map(n=>esc(sourceByName(n).title)).join(' · ')+'<br>'+esc(l.range)+'</p>'+(l.starter?'<p class="starter">'+esc(tx(l.starter))+'</p>':'')+'<ol class="task-steps">'+l.tasks.map(s=>'<li>'+esc(tx(s))+'</li>').join('')+'</ol><a class="btn" href="'+esc(primary.url)+'" target="_blank" rel="noopener noreferrer">'+t('Buka proyek BSD ↗','Open BSD project ↗')+'</a></section><section class="panel challenge-card"><p class="eyebrow">02 · '+t('COBA SENDIRI','TRY IT YOURSELF')+'</p><h2>'+t('Tantangan','Challenge')+'</h2><p>'+esc(tx(l.challenge))+'</p><p class="small">'+esc(tx(l.check))+'</p><div class="result-target"><b>'+t('Tunjukkan hasil: ','Show your result: ')+'</b>'+esc(tx(l.result))+'</div></section><section class="panel result-card"><h2>'+t('Simpan hasilmu','Save your result')+'</h2><label for="evidence">'+t('Tautan karya · perubahan & prediksimu','Project link · your change & prediction')+'</label><textarea rows="2" id="evidence" placeholder="'+t('Tautan + saya mengubah… saya memprediksi…','Link + I changed… I predict…')+'">'+esc(r.evidence)+'</textarea><label for="reflection">'+t('Hasil uji & satu keterbatasan','Test results & one limitation')+'</label><textarea rows="2" id="reflection" placeholder="'+t('Input uji → hasil aktual. Batas yang masih ada…','Test input → actual result. Remaining limit…')+'">'+esc(r.reflection)+'</textarea><p class="small">'+(storageAvailable?t('Tersimpan otomatis pada browser ini. Tunjukkan karya kepada guru.','Saved automatically on this browser. Show your work to your teacher.'):t('Unduh catatan untuk menyimpan hasil.','Download your notes to keep your work.'))+'</p><div class="actions"><button id="complete" class="btn '+(r.done?'done':'')+'">'+(r.done?t('✓ Bukti ditandai siap','✓ Evidence marked ready'):t('Tandai bukti siap','Mark evidence ready'))+'</button><button id="download-note" class="btn secondary">'+t('Unduh catatan','Download notes')+'</button></div></section><details class="panel optional"><summary>'+t('Ringkasan & kuis latihan (pilihan)','Summary & practice quiz (optional)')+'</summary><div><p class="concept-summary">'+esc(tx(l.learn))+'</p><p class="small">'+t('2 soal pendamping · dapat diulang · bukan nilai resmi BSD.','2 companion questions · retry any time · separate from official BSD grades.')+'</p><div id="practice-quiz">'+quizHTML(l)+'</div></div></details>'+(teacherMode()?'<details class="panel teacher-details"><summary>'+t('Pengantar & catatan guru','Teacher introduction & notes')+'</summary>'+teacherLessonHTML(l)+'</details>':'')+'<div class="actions lesson-next">'+(l.id>1?'<a class="btn secondary" href="#lesson/'+(l.id-1)+'">← '+t('Sebelumnya','Previous')+'</a>':'')+(l.id<LESSONS.length?'<a class="btn secondary" href="#lesson/'+(l.id+1)+'">'+t('Pertemuan ','Meeting ')+(l.id+1)+' →</a>':'<a class="btn secondary" href="#project">'+t('Demo final →','Final demo →')+'</a>')+'</div></div>';}
function quizHTML(l){const q=lessonRecord(l.id).quiz,finished=q.last!==null;return (finished?'<div class="quiz-result" role="status"><b>'+q.last+'/100</b> · '+t('terbaik: ','best: ')+q.best+'/100</div>':'')+'<form id="quiz-form" class="quiz">'+l.questions.map((question,i)=>'<fieldset><legend>'+(i+1)+'. '+esc(tx(question.stem))+'</legend>'+question.options.map((option,j)=>'<label><input type="radio" name="q'+i+'" value="'+j+'" '+(q.draft[i]===j?'checked':'')+' '+(finished?'disabled':'')+' required><span>'+esc(tx(option))+'</span></label>').join('')+(finished?'<p class="explanation">'+(q.draft[i]===question.key?'✓ ':'↗ ')+t('Jawaban: ','Answer: ')+esc(tx(question.options[question.key]))+'. '+esc(tx(question.why))+'</p>':'')+'</fieldset>').join('')+'<button class="btn" type="submit" '+(finished?'disabled':'')+'>'+t('Periksa jawaban','Check answers')+'</button></form>'+(finished?'<button class="btn secondary" id="retry" style="margin-top:12px">'+t('Ulangi latihan','Retry practice')+'</button>':'');}
function recordQuiz(l,answers){if(answers.length!==l.questions.length||answers.some(a=>!Number.isInteger(a)||a<0||a>2))return false;const q=lessonRecord(l.id).quiz,score=Math.round(answers.filter((a,i)=>a===l.questions[i].key).length/answers.length*100);q.draft=answers.slice();q.last=score;q.best=q.best===null?score:Math.max(q.best,score);save();return true;}
function bindQuiz(l){const form=$('quiz-form');form.addEventListener('change',()=>{const q=lessonRecord(l.id).quiz;q.draft=l.questions.map((_,i)=>{const el=form.querySelector('input[name="q'+i+'"]:checked');return el?Number(el.value):null;});save();});form.addEventListener('submit',event=>{event.preventDefault();const answers=l.questions.map((_,i)=>{const el=form.querySelector('input[name="q'+i+'"]:checked');return el?Number(el.value):null;});if(!recordQuiz(l,answers))return;$('practice-quiz').innerHTML=quizHTML(l);bindQuiz(l);});if($('retry'))$('retry').addEventListener('click',()=>{const q=lessonRecord(l.id).quiz;q.last=null;q.draft=[];save();$('practice-quiz').innerHTML=quizHTML(l);bindQuiz(l);});}
function bindLesson(l){for(const key of ['evidence','reflection'])$(key).addEventListener('input',()=>{lessonRecord(l.id)[key]=$(key).value;save();});$('complete').addEventListener('click',()=>{const r=lessonRecord(l.id);if(!r.done&&(!r.evidence.trim()||!r.reflection.trim())){toast(t('Isi perubahan dan hasil uji dahulu.','Add your change and test results first.'));return;}r.done=!r.done;save();$('complete').classList.toggle('done',r.done);$('complete').textContent=r.done?t('✓ Bukti ditandai siap','✓ Evidence marked ready'):t('Tandai bukti siap','Mark evidence ready');toast(t('Catatan latihan diperbarui.','Practice record updated.'));});$('download-note').addEventListener('click',()=>download('ai-studio-meeting-'+l.id+'.txt',noteText(l)));bindQuiz(l);}
function noteText(l){const r=lessonRecord(l.id);return l.id+'. '+tx(l.title)+'\n\n'+t('Hasil: ','Result: ')+r.evidence+'\n'+t('Refleksi: ','Reflection: ')+r.reflection+'\n'+t('Selesai: ','Complete: ')+r.done+'\n'+t('Skor latihan terbaik: ','Best practice score: ')+(r.quiz.best??'—')+'\n\n'+t('Catatan pribadi pada browser ini; bukan nilai resmi.','Personal browser notes; separate from official grades.');}
function download(name,text){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function teacherLessonHTML(l){if(!teacherMode())return '';return '<p><b>'+t('Pengantar lisan: ','Spoken introduction: ')+'</b>'+esc(tx(l.goal))+' '+esc(tx(l.learn))+' '+t('Hari ini buka ','Today open ')+esc(l.range)+'. '+t('Hasil yang saya harapkan: ','Expected result: ')+esc(tx(l.result))+'</p><p><b>'+t('Persiapan & batas: ','Preparation & scope: ')+'</b>'+esc(tx(l.prep))+'</p><p><b>'+t('Saat berkeliling: ','While circulating: ')+'</b>'+esc(tx(l.oral))+'</p><p><b>WKA / BCW: </b>'+esc(tx(l.wka))+'</p><h3>'+t('Agenda 80 menit','80-minute agenda')+'</h3><ul>'+l.times.map(([s,n])=>'<li>'+esc(tx(s.split('|')))+' · '+n+' '+t('menit','minutes')+'</li>').join('')+'</ul>';}
function teacherHTML(){if(!teacherMode())return homeHTML();return '<p class="eyebrow">'+t('KELAS 11 · PANDUAN GURU','GRADE 11 · TEACHER GUIDE')+'</p><h1>'+t('Minta prediksi. Periksa bukti.','Ask for predictions. Check evidence.')+'</h1><div class="teacher-grid"><section class="panel"><h2>'+t('14 pertemuan setelah Webcam Live Classifier','14 meetings after Webcam Live Classifier')+'</h2><p>'+t('14 × 80 menit = 18 jam 40 menit. Overview seluruh course BSD mengalokasikan 25 jam. Ini rencana lanjutan, dengan beberapa proyek 2 jam dipadatkan memakai checkpoint atau pengerjaan mandiri. Jika siswa telah menyelesaikan coding live classifier juga, gunakan salinan mereka untuk modifikasi pada pertemuan 2–3.','14 × 80 minutes = 18 hours 40 minutes. The complete BSD course overview allocates 25 hours. This continuation plan condenses some 2-hour projects using checkpoints or independent work. If live classifier coding is already complete, use students’ copies for modifications in meetings 2–3.')+'</p><p>'+t('Pembuka: tujuan, demo, satu pertanyaan lisan. Saat praktik: minta siswa menunjuk kode, memprediksi perubahan, menguji, lalu menjelaskan hasil. Beri feedback sebelum siswa merevisi.','Open with the goal, a demo, and one spoken question. During practice, ask students to point to code, predict a change, test, and explain the result. Give feedback before they revise.')+'</p><h3>'+t('Tiga checkpoint formatif','Three formative checkpoints')+'</h3><ul>'+COURSE.checkpoints.map(c=>'<li><a href="#lesson/'+c.meeting+'">'+c.name+' · '+t('Pertemuan ','Meeting ')+c.meeting+'</a>: '+esc(tx(c.focus))+'</li>').join('')+'</ul><p>'+t('Feedback: apakah perubahan terarah, perbandingan adil, dan penjelasan cocok dengan bukti? Pada pertemuan berikutnya siswa menunjukkan revisi singkat. Checkpoint ini rekomendasi kegiatan; tipe dan bobot penilaian resmi mengikuti buku nilai yang sudah ada.','Feedback: is the change purposeful, the comparison fair, and the explanation supported by evidence? Students show a brief revision next meeting. These checkpoints are activity recommendations; official assessment types and weights follow the existing gradebook.')+'</p><div class="actions"><button id="download-guide" class="btn">'+t('Unduh 14 panduan & kunci latihan','Download 14 guides & practice keys')+'</button><a class="btn secondary" href="#project">'+t('Demo & kriteria penilaian','Demo & assessment criteria')+'</a></div></section><section class="panel"><h2>'+t('Peta materi','Learning map')+'</h2><div class="table-scroll"><table class="teacher-map"><thead><tr><th>#</th><th>BSD</th><th>'+t('Hasil','Result')+'</th></tr></thead><tbody>'+LESSONS.map(l=>'<tr><td><a href="#lesson/'+l.id+'">'+l.id+'</a></td><td>'+esc(l.range)+'</td><td>'+esc(tx(l.result))+'</td></tr>').join('')+'</tbody></table></div></section>'+LESSONS.map(l=>'<details class="panel teacher-details"><summary>'+l.id+'. '+esc(tx(l.title))+'</summary>'+teacherLessonHTML(l)+'</details>').join('')+'<details class="panel teacher-details"><summary>'+t('Sumber & catatan akurasi','Sources & accuracy notes')+'</summary><p>'+t('Diperiksa 13 Oktober 2026: 15 definisi proyek BSD (163 langkah) dan 6 PDF welcome, overview, progression, serta konsep AI. Pertanyaan web ialah 28 soal pendamping asli yang diselaraskan dengan instruksi dan kode, bukan salinan atau kunci kuis resmi BSD.','Reviewed on 13 October 2026: 15 BSD project definitions (163 steps) and 6 welcome, overview, progression, and AI-concept PDFs. The website contains 28 original companion questions aligned to instructions and code, rather than copied official BSD quizzes or answer keys.')+'</p><ul><li>'+t('Adjustable Accuracy: slider mengubah K KNN. adjustConfidence memakai faktor K dan Math.random(); confidence tampilan bukan ukuran akurasi.','Adjustable Accuracy: the slider changes KNN K. adjustConfidence uses a K factor and Math.random(); displayed confidence is not measured accuracy.')+'</li><li>'+t('Music Generator memutar suara berdasarkan klasifikasi; Digital Assistant memakai if/else string. Keduanya bukan model generatif.','Music Generator plays sounds based on classification; Digital Assistant uses string if/else. Neither is a generative model.')+'</li><li>'+t('Chess memakai evaluasi/pencarian; navigasi memakai perintah, kondisi, pathfinding, dan memori gerak. Nama fastest bukan bukti optimalitas global.','Chess uses evaluation/search; navigation uses commands, conditions, pathfinding, and move memory. The name fastest is not proof of global optimality.')+'</li></ul>'+BSD_SOURCES.map(s=>'<p class="source-link"><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a> · '+s.steps+' '+t('langkah','steps')+' · revision '+esc(s.revision)+' · <a href="'+esc(s.definition)+'" target="_blank" rel="noopener noreferrer">'+t('Definisi sumber','Source definition')+'</a></p>').join('')+'<p class="source-link"><a href="https://app.bsd.education/resources/CORE%20CONTENT/TechNovators/Code%20the%20Future%20with%20Artificial%20Intelligence/General%20Resources/English/Code%20the%20Future%20with%20AI%20-%20Overview%20Document.pdf" target="_blank" rel="noopener noreferrer">BSD Overview</a> · <a href="https://app.bsd.education/resources/CORE%20CONTENT/Standard%20Alignments/Course%20Progression/TechNovators%20Course%20Progression%20Documents/Code%20the%20Future%20with%20Artificial%20Intelligence%20Course%20Progression.pdf" target="_blank" rel="noopener noreferrer">BSD Progression</a></p></details></div>';}

function guideText(){if(!teacherMode())return '';return '# Grade 11 · Code the Future with AI\n\n14 × 80 minutes, after Webcam Live Classifier. F1: meeting 1; F2: meeting 4; F3: meeting 13. Checkpoints/independent continuation for condensed projects. Official grades follow the existing gradebook.\n\n'+LESSONS.map(l=>'## '+l.id+'. '+tx(l.title)+'\n'+tx(l.goal)+'\n'+tx(l.learn)+'\nBSD: '+l.range+'\n\n'+l.tasks.map((s,i)=>(i+1)+'. '+tx(s)).join('\n')+'\nChallenge: '+tx(l.challenge)+'\nResult: '+tx(l.result)+'\nTest: '+tx(l.check)+'\nPreparation: '+tx(l.prep)+'\nSpoken question: '+tx(l.oral)+'\nWKA/BCW: '+tx(l.wka)+'\nAgenda: '+l.times.map(([s,n])=>tx(s.split('|'))+' '+n+' minutes').join('; ')+'\nPractice keys (original companion bank):\n'+l.questions.map(q=>tx(q.stem)+'\n'+tx(q.options[q.key])+' — '+tx(q.why)).join('\n\n')).join('\n\n')+'\n\nCriteria: '+COURSE.rubric.map(r=>tx(r.label)+' '+r.weight+'% — '+tx(r.description)).join('\n')+'\n\nSources:\n'+BSD_SOURCES.map(s=>s.title+' — '+s.definition).join('\n');}

function projectHTML(){return '<p class="eyebrow">'+t('DEMO INDIVIDUAL · PERTEMUAN 14','INDIVIDUAL DEMO · MEETING 14')+'</p><h1>'+t('Karyamu. Bukti ujimu.','Your work. Your test evidence.')+'</h1><div class="classroom"><section class="panel"><h2>'+t('Siapkan empat hal','Prepare four things')+'</h2><ol class="project-list">'+[t('Tautan satu karya yang kamu modifikasi.','A link to one project you modified.'),t('Perubahan dan alasan; tunjukkan kode sebelum/sesudah.','The change and its reason; show before/after code.'),t('Input uji, hasil aktual, dan satu keterbatasan.','Test inputs, actual results, and one limitation.'),t('Demo 2–3 menit: jelaskan alur, prediksi perubahan kecil, lalu jalankan.','A 2–3 minute demo: explain the flow, predict a small change, then run it.')].map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol><a class="btn" href="#lesson/14">'+t('Buka tugas demo →','Open the demo task →')+'</a></section><section class="panel"><h2>'+t('Kriteria karya','Work criteria')+'</h2><ul class="project-list">'+COURSE.rubric.map(r=>'<li><b>'+esc(tx(r.label))+' · '+r.weight+'%</b><br>'+esc(tx(r.description))+'</li>').join('')+'</ul><p class="small">'+t('Mengikuti kriteria AI yang sudah ada di CS.Report. Jenis dan bobot nilai resmi mengikuti buku nilai guru. Kuis dan tanda siap pada web ini tidak otomatis menjadi nilai.','Uses the existing CS.Report AI criteria. Official assessment types and weights follow the teacher’s gradebook. Website quizzes and readiness marks do not automatically become grades.')+'</p></section></div>';}

function route(){const [page,id]=location.hash.replace(/^#/,'').split('/');currentLesson=null;if(page==='teacher'&&!teacherMode()){location.hash='#home';return route();}let html;if(page==='lesson'){currentLesson=LESSONS.find(l=>l.id===Number(id));if(!currentLesson){location.hash='#home';return route();}html=lessonHTML(currentLesson);}else if(page==='teacher')html=teacherHTML();else if(page==='project')html=projectHTML();else html=homeHTML();$('main').innerHTML=html;if(currentLesson)bindLesson(currentLesson);if(page==='teacher')$('download-guide').addEventListener('click',()=>download('grade11-ai-studio-guides-'+language+'.md',guideText()));document.title=(currentLesson?tx(currentLesson.title)+' · ':'')+'AI Studio · Grade 11';window.scrollTo({top:0,behavior:'instant'});$('main').focus({preventScroll:true});}
$('language').addEventListener('change',event=>{language=event.target.value;try{localStorage.setItem('cs-report-grade11-language',language);}catch{}const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url);localizeShell();if(g11Session){$('learner-class').textContent=teacherMode()?t('Review guru · Kelas 11','Teacher review · Grade 11'):t('Kelas ','Class ')+g11Session.className;route();}});
async function start(){localizeShell();if(!(await initializeG11Access()))return;restorePractice();$('nav-teacher').hidden=!teacherMode();$('review-banner').hidden=!(teacherMode()||g11Session.isLocalPreview);$('review-banner').textContent=teacherMode()?t('Review guru. Catatan ini terpisah dari siswa.','Teacher review. These records are separate from students.'):t('Pratinjau lokal dengan siswa uji. Tanpa data siswa nyata.','Local preview with a test student. No real student data.');window.addEventListener('hashchange',route);route();}
start().catch(()=>{$('gate-copy').textContent=t('Materi belum termuat. Buka ulang dari CS.Report.','Materials could not load. Reopen from CS.Report.');});
